node.code:
import json
async def main(args):
    """变更调用原文 → 文本（供 update_wiki 子 Agent 直接看改动，不必 read_file 重读源文件）。"""
    p = args.params
    calls = p.get("changed_calls") or []
    if isinstance(calls, str):
        try: calls = json.loads(calls)
        except Exception: calls = []
    if not calls:
        return {"calls_text": "(本轮无文件变更)"}
    lines = []
    for i, c in enumerate(calls, 1):
        ch = ", ".join(f"{x.get('file')}({x.get('change')})" for x in (c.get("changed_files") or [])[:8])
        a_s = json.dumps(c.get("arguments") or {}, ensure_ascii=False)
        if len(a_s) > 600: a_s = a_s[:600] + "...(截断)"
        res = str(c.get("result_preview") or "")
        lines.append(f"{i}. {c.get('name')}({a_s})")
        if ch: lines.append(f"   变更: {ch}")
        if res: lines.append(f"   结果: {res[:400]}")
    return {"calls_text": "\n".join(lines)}

